package kernels

// The FMA kernels (Round 41), generated by genFMAFiles in
// asmgen/amd64/gen.go into fma_amd64.s, fmasplit_amd64.s and
// fmasplit512_amd64.s: every pass kernel that multiplies by twiddles, built a
// second time with that product fused. Each is its default twin's code with
// one difference, the twiddle product of every output j >= 1 at every point
// i >= 1 (skEmit.fmaProduct):
//
//	re = fma(yr, wr, −(yi·wi)),  im = fma(yi, wr, yr·wi)
//
// two roundings instead of three, computed by VMULPD then VFMADDSUB231PD on
// interleaved data and by VMULPD then VFMSUB231PD or VFMADD231PD on split
// data. The butterflies, the blends that keep the point i = 0 unmultiplied,
// the layouts and the loops are the default kernels', so an FMA kernel is
// bit-identical to the Go pass with cmulFMA in place of the complex product
// (the fft package's passScalarFMA), not to the default pass. The final
// passes (ido == 1) have no twiddles: an FMA plan runs the default ones.
//
// Nothing here runs unless a plan was built for it: the fft package builds
// FMA plans only where UseFMA is on, for the callers that ask for them
// (Options.FMA).

// UseFMA reports whether the CPU runs the FMA kernels: AVX2, which every
// FMA kernel also uses, and FMA3, a CPUID bit of its own that a hypervisor
// can mask apart from AVX2 (supportsFMA, go-asmgen's probe, which also checks
// that the OS saves YMM state). The fft package reads it when it builds a
// plan; a variable so that its tests can build the default plan on a machine
// with FMA. Setting it on a CPU without FMA3 makes the FMA kernels fault.
var UseFMA = useAVX2 && supportsFMA()

// supportsFMA is the go-asmgen FMA probe (cpu_amd64.s).
func supportsFMA() bool

// The FMA twins of skPass256, skPass512, skBatch256, skStrided256 and
// skStrided512, by radix.
var (
	skPass256FMA = [21]skPassFn{2: skPass2AVX2FMA, 3: skPass3AVX2FMA, 4: skPass4AVX2FMA, 5: skPass5AVX2FMA, 8: skPass8AVX2FMA,
		10: skPass10AVX2FMA, 12: skPass12AVX2FMA, 15: skPass15AVX2FMA, 16: skPass16AVX2FMA, 20: skPass20AVX2FMA, 9: csPass9AVX2FMA}
	skPass512FMA    = [21]skPassFn{2: skPass2AVX512FMA, 4: skPass4AVX512FMA, 8: skPass8AVX512FMA}
	skBatch256FMA   = [9]skBatchFn{2: skBatch2AVX2FMA, 3: skBatch3AVX2FMA, 4: skBatch4AVX2FMA, 5: skBatch5AVX2FMA, 8: skBatch8AVX2FMA}
	skStrided256FMA = [9]skStridedFn{4: skStrided4AVX2FMA, 8: skStrided8AVX2FMA}
	skStrided512FMA = [9]skStridedFn{4: skStrided4AVX512FMA, 8: skStrided8AVX512FMA}
)

// The FMA twins of the split kernels, by radix and mode, per direction.
var (
	skSplitFwdFMA = [9][5]skPassFn{
		4: {splitOut: skSplit4ISFwdFMA, splitBoth: skSplit4SSFwdFMA, splitIn: skSplit4SIFwdFMA, splitNone: skSplit4IIFwdFMA},
		8: {splitOut: skSplit8ISFwdFMA, splitBoth: skSplit8SSFwdFMA, splitIn: skSplit8SIFwdFMA, splitNone: skSplit8IIFwdFMA},
		3: {splitOut: skSplit3ISFwdFMA, splitBoth: skSplit3SSFwdFMA, splitIn: skSplit3SIFwdFMA, splitNone: skSplit3IIFwdFMA},
		5: {splitOut: skSplit5ISFwdFMA, splitBoth: skSplit5SSFwdFMA, splitIn: skSplit5SIFwdFMA, splitNone: skSplit5IIFwdFMA},
	}
	skSplitInvFMA = [9][5]skPassFn{
		4: {splitOut: skSplit4ISInvFMA, splitBoth: skSplit4SSInvFMA, splitIn: skSplit4SIInvFMA, splitNone: skSplit4IIInvFMA},
		8: {splitOut: skSplit8ISInvFMA, splitBoth: skSplit8SSInvFMA, splitIn: skSplit8SIInvFMA, splitNone: skSplit8IIInvFMA},
		3: {splitOut: skSplit3ISInvFMA, splitBoth: skSplit3SSInvFMA, splitIn: skSplit3SIInvFMA, splitNone: skSplit3IIInvFMA},
		5: {splitOut: skSplit5ISInvFMA, splitBoth: skSplit5SSInvFMA, splitIn: skSplit5SIInvFMA, splitNone: skSplit5IIInvFMA},
	}
	intelSplit512FwdFMA = [9][5]skPassFn{
		4: {splitOut: intelSplit512R4ISFwdFMA, splitBoth: intelSplit512R4SSFwdFMA, splitIn: intelSplit512R4SIFwdFMA, splitNone: intelSplit512R4IIFwdFMA},
		8: {splitOut: intelSplit512R8ISFwdFMA, splitBoth: intelSplit512R8SSFwdFMA, splitIn: intelSplit512R8SIFwdFMA, splitNone: intelSplit512R8IIFwdFMA},
	}
	intelSplit512InvFMA = [9][5]skPassFn{
		4: {splitOut: intelSplit512R4ISInvFMA, splitBoth: intelSplit512R4SSInvFMA, splitIn: intelSplit512R4SIInvFMA, splitNone: intelSplit512R4IIInvFMA},
		8: {splitOut: intelSplit512R8ISInvFMA, splitBoth: intelSplit512R8SSInvFMA, splitIn: intelSplit512R8SIInvFMA, splitNone: intelSplit512R8IIInvFMA},
	}
)

